func assertSingleValue(dec *json.Decoder) error {
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		return errTrailingJSON
	}
	return nil
}

// validateConfig 校验配置必须是合法的 JSON 对象，并返回独立副本。
func validateConfig(raw json.RawMessage) (json.RawMessage, error) {
	if _, ok := decodeObject(raw); !ok {
		return nil, ErrInvalidConfig
	}
	return cloneRaw(raw), nil
}

// rawEqual 比较两份 JSON 值是否语义相等：忽略对象字段顺序，
// 数字按数值比较（1 与 1.0 相等），其余按类型与值比较。
func rawEqual(a, b json.RawMessage) bool {
	av, err := decodeValue(a)
	if err != nil {
		return false
	}
	bv, err := decodeValue(b)
	if err != nil {
		return false
	}
	return jsonDeepEqual(av, bv)
}

func decodeValue(raw json.RawMessage) (any, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	if err := assertSingleValue(dec); err != nil {
		return nil, err
	}
	return v, nil
}

func jsonDeepEqual(a, b any) bool {
	switch av := a.(type) {
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, va := range av {
			vb, ok := bv[k]
			if !ok || !jsonDeepEqual(va, vb) {
				return false
			}
		}
		return true
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !jsonDeepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case json.Number:
		bv, ok := b.(json.Number)
		if !ok {
			return false
		}
		return numberEqual(av, bv)
	default:
		return reflect.DeepEqual(a, b)
	}
}

func numberEqual(a, b json.Number) bool {
	if a.String() == b.String() {
		return true
	}
	ra, okA := new(big.Rat).SetString(a.String())
	rb, okB := new(big.Rat).SetString(b.String())
	if okA && okB {
		return ra.Cmp(rb) == 0
	}
	return false
}

func cloneRaw(raw json.RawMessage) json.RawMessage {
	if raw == nil {
		return nil
	}
	out := make(json.RawMessage, len(raw))
	copy(out, raw)
	return out
}

