9	// diskBatch 是批量请求记录的磁盘格式。
10	type diskBatch struct {
11		ID       string         `json:"id"`
12		Operator string         `json:"operator"`
13		Time     time.Time      `json:"time"`
14		Devices  []diskBatchDev `json:"devices"`
15	}
16	
17	type diskBatchDev struct {
18		DeviceID    string          `json:"deviceId"`
19		Revision    uint64          `json:"revision"`
20		NewRevision uint64          `json:"newRevision"`
21		Config      json.RawMessage `json:"config"`
22	}
23	
24	func (s *Store) marshalBatches() map[string]diskBatch {
25		out := make(map[string]diskBatch, len(s.batches))
26		for id, b := range s.batches {
27			db := diskBatch{
28				ID:       b.ID,
29				Operator: b.Operator,
30				Time:     b.Time,
31				Devices:  make([]diskBatchDev, 0, len(b.Devices)),
32			}
33			for _, d := range b.Devices {
34				db.Devices = append(db.Devices, diskBatchDev{
35					DeviceID:    d.DeviceID,
36					Revision:    d.Revision,
37					NewRevision: d.NewRevision,
38					Config:      cloneRaw(d.Config),
39				})
40			}
41			out[id] = db
42		}
43		return out
44	}
45	
46	// restoreBatches 恢复批量请求记录并做双向一致性校验。
47	//
48	// 正向：每条成功请求中的每台设备，其审计里必须恰好存在一条对应记录——
49	// 请求标识与本次新修订号一致、操作者相同、时间为同一时刻、修改后配置与
50	// 请求提交的完整配置语义相等（忽略 JSON 空白与对象字段顺序，数字按数值
51	// 比较，数组有序，字段缺失与 null 不同）。
52	// 反向：审计中凡带批量请求标识的记录，必须对应那个请求实际包含的设备及
53	// 其新修订号，不能仅因请求存在就接受。
54	// 任何不一致都返回 ErrCorruptStorage 拒绝打开整个存储，不自动修正、
55	// 不丢弃记录。旧存储没有批量记录时 disk 为 nil，正常打开。
56	func (s *Store) restoreBatches(disk map[string]diskBatch) error {
57		out := make(map[string]*batchRequestState, len(disk))
58		// expected 按请求标识记录每台设备实际参与修改时的新修订号，供反向核对。
59		expected := make(map[string]map[string]uint64, len(disk))
60		for id, db := range disk {
61			if id == "" || db.ID != id {
62				return fmt.Errorf("%w: batch request id mismatch", ErrCorruptStorage)
63			}
64			if db.Operator == "" || db.Time.IsZero() {
65				return fmt.Errorf("%w: batch request %s invalid", ErrCorruptStorage, id)
66			}
67			if len(db.Devices) == 0 {
68				return fmt.Errorf("%w: batch request %s has no devices", ErrCorruptStorage, id)
69			}
70			rec := &batchRequestState{ID: id, Operator: db.Operator, Time: db.Time}
71			seen := map[string]bool{}
72			devRevs := make(map[string]uint64, len(db.Devices))
73			for _, dd := range db.Devices {
74				if dd.DeviceID == "" || seen[dd.DeviceID] {
75					return fmt.Errorf("%w: batch request %s device list invalid", ErrCorruptStorage, id)
76				}
77				seen[dd.DeviceID] = true
78				dev, ok := s.devices[dd.DeviceID]
79				if !ok {
80					return fmt.Errorf("%w: batch request %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
81				}
82				if _, ok := decodeObject(dd.Config); !ok {
83					return fmt.Errorf("%w: batch request %s device %s config invalid", ErrCorruptStorage, id, dd.DeviceID)
84				}
85				if dd.NewRevision != dd.Revision+1 || dev.Revision < dd.NewRevision {
86					return fmt.Errorf("%w: batch request %s device %s revision mismatch", ErrCorruptStorage, id, dd.DeviceID)
87				}
88				// 设备审计中必须恰好存在一条与该请求项描述同一次修改的记录。
89				matches := 0
90				for _, a := range dev.Audit {
91					if a.RequestID != id || a.Revision != dd.NewRevision {
92						continue
93					}
94					matches++
95					if a.Operator != db.Operator || !a.Time.Equal(db.Time) || !rawEqual(a.After, dd.Config) {
96						return fmt.Errorf("%w: batch request %s device %s audit content mismatch",
97							ErrCorruptStorage, id, dd.DeviceID)
98					}
99				}
100				if matches != 1 {
101					return fmt.Errorf("%w: batch request %s device %s audit missing",
102						ErrCorruptStorage, id, dd.DeviceID)
103				}
104				devRevs[dd.DeviceID] = dd.NewRevision
105				rec.Devices = append(rec.Devices, batchDeviceState{
106					DeviceID:    dd.DeviceID,
107					Revision:    dd.Revision,
108					NewRevision: dd.NewRevision,
109					Config:      cloneRaw(dd.Config),
110				})
111			}
112			expected[id] = devRevs
113			out[id] = rec
114		}
115		// 反向核对：审计中的非空请求标识必须对应一条实际包含该设备、且新修订号
116		// 一致的批量记录（单设备修改的审计标识为空，无需补填）。
117		for devID, dev := range s.devices {
118			for _, a := range dev.Audit {
119				if a.RequestID == "" {
120					continue
121				}
122				devs, ok := expected[a.RequestID]
123				if !ok {
124					return fmt.Errorf("%w: device %s audit references unknown batch request %s",
125						ErrCorruptStorage, devID, a.RequestID)
126				}
127				if rev, ok := devs[devID]; !ok || rev != a.Revision {
128					return fmt.Errorf("%w: device %s audit misattached to batch request %s",
129						ErrCorruptStorage, devID, a.RequestID)
130				}
131			}
132		}
133		s.batches = out
134		return nil
135	}
